type RawSourceInventoryBase = Omit<
  EmpiresRawSourceInventoryEntry,
  | 'messageIds'
  | 'residualDisposition'
  | 'residualOwner'
  | 'residualConsumer'
  | 'residualTestEvidence'
  | 'residualDesignerQuestion'
>

function withResidualPolicy(source: RawSourceInventoryBase): EmpiresRawSourceInventoryEntry {
  const messageIds = RAW_SOURCE_MESSAGE_ID_SNAPSHOTS[source.id]
  if (messageIds === undefined) throw new Error(`P12B source ${source.id} has no message-ID snapshot`)
  const residualDisposition = source.role === 'out' ? 'out' : 'review'
  return {
    ...source,
    messageIds: messageIds === null ? null : [...messageIds],
    residualDisposition,
    residualOwner: residualDisposition === 'out'
      ? 'none; source is explicitly excluded from completion scope'
      : 'P12B manual raw-source audit / future content tranche',
    residualConsumer: residualDisposition === 'out'
      ? 'None'
      : 'None until manual extraction promotes an exact row into rawCatalogGroups',
    residualTestEvidence: ['phase12b.spec.ts frozen source-message spine'],
    ...(residualDisposition === 'review'
      ? {
          residualDesignerQuestion:
            `Which unclassified message remainder in ${source.id} is current executable intent, and what stable identity, owner, consumer and disposition does it require?`,
        }
      : {}),
  }
}

