function familyFor(key: string): Family {
  const family = FAMILIES.find(candidate => candidate.prefixes.some(prefix => key.startsWith(prefix)))
  if (!family) throw new Error('P12B carrier snapshot has no family for ' + key)
  return family
}

function dispositionFor(
  key: string,
  availability: EmpiresConfigCarrierAvailability,
): EmpiresContentDisposition {
  if (availability === 'review' || CONFIGURED_REVIEW_KEYS.has(key)) return 'review'
  if (CONFIGURED_BLOCKED_SUBSTRATE_KEYS.has(key)) return 'blocked-substrate'
  if (CONFIGURED_BLOCKED_SEMANTIC_KEYS.has(key)) return 'blocked-semantic'
  if (availability === 'deferred') {
    if (key.startsWith('card-face:') && !MAPPED_BLOCKED_CARD_KEYS.has(key)) return 'review'
    return 'blocked-semantic'
  }
  return 'live'
}

const configGroupBuckets = new Map<string, {
  family: Family
  disposition: EmpiresContentDisposition
  expectedAvailability: EmpiresConfigCarrierAvailability
  keys: string[]
}>()

for (const expectedAvailability of ['configured', 'deferred', 'review'] as const) {
  for (const key of EMPIRES_CONTENT_CARRIER_SNAPSHOT[expectedAvailability]) {
    const family = familyFor(key)
    const disposition = dispositionFor(key, expectedAvailability)
    const bucketId = [family.id, disposition, expectedAvailability].join(':')
    const bucket = configGroupBuckets.get(bucketId) ?? {
      family,
      disposition,
      expectedAvailability,
      keys: [],
    }
    bucket.keys.push(key)
    configGroupBuckets.set(bucketId, bucket)
  }
}

